UNITS = [
 {"unit":"Unit 21：造格 〜と一緒に／〜として","gp":"造格",
  "gDetail":"造格（творительный падеж）は「〜で（道具）」「〜と一緒に（с＋造格）」「〜として・〜になる（職業・変化）」を表します。語尾の目安は 男性・中性 -ом/-ем、女性 -ой/-ей、複数 -ами/-ями。заниматься／интересоваться／пользоваться／стать／работать などは造格をとる動詞としてセットで覚えます。前置詞 с, за, под, над, перед, между も造格と一緒に使います。",
  "s":[
  ("私は母と一緒に住んでいます。","Я живу́ с ма́мой.","ヤー ジヴー ス マーマイ。","с＋造格で「〜と一緒に」。ма́ма → ма́мой（女性 -а → -ой）。"),
  ("私はコーヒーをミルク入りで飲みます。","Я пью ко́фе с молоко́м.","ヤー ピユー コーフィ ス マラコーム。","с＋造格で「〜入りの・〜付きの」。молоко́ → молоко́м（中性 -о → -ом）。"),
  ("父はエンジニアとして働いています。","Па́па рабо́тает инжене́ром.","パーパ ラボータイト インジニェーラム。","рабо́тать＋造格で職業「〜として働く」。前置詞は不要です。"),
  ("私は医者になりたいです。","Я хочу́ стать врачо́м.","ヤー ハチュー スターチ ヴラチョーム。","стать＋造格で「〜になる」。врач → врачо́м。"),
  ("息子はサッカーをしています。","Сын занима́ется футбо́лом.","スィーン ザニマーイッツァ フドボーラム。","занима́ться＋造格で「（スポーツ・勉強を）する」。"),
  ("私は音楽に興味があります。","Я интересу́юсь му́зыкой.","ヤー インチリスーユシ ムーズィカイ。","интересова́ться＋造格で「〜に興味がある」。му́зыка → му́зыкой。"),
  ("私たちは友達と会います。","Мы встреча́емся с друзья́ми.","ミー フストリチャーイムシャ ズ ドルジヤーミ。","複数の造格は -ами／-ями。друзья́ → друзья́ми。"),
  ("彼女と知り合いになりたいです。","Я хочу́ познако́миться с ней.","ヤー ハチュー パズナコーミッツァ ス ニェイ。","代名詞の造格：она́ → ней（前置詞の後は н- が付きます）。"),
  ("鉛筆で書いてください。","Пиши́те карандашо́м, пожа́луйста.","ピシーチェ カランダショーム、パジャールスタ。","道具「〜で」は前置詞なしの造格。каранда́ш → карандашо́м。"),
  ("ナイフはテーブルの下にあります。","Нож лежи́т под столо́м.","ノーシ リジート パト スタローム。","под＋造格で「〜の下に（場所）」。стол → столо́м。"),
  ("家の前に車が止まっています。","Пе́ред до́мом стои́т маши́на.","ピェーリド ドーマム スタイート マシーナ。","пе́ред＋造格で「〜の前に」。дом → до́мом。"),
  ("薬局は銀行と郵便局の間にあります。","Апте́ка ме́жду ба́нком и по́чтой.","アプチェーカ ミェージドゥ バーンカム イ ポーチタイ。","ме́жду＋造格で「〜と〜の間に」。両方とも造格になります。"),
  ("誕生日おめでとう！","Поздравля́ю с днём рожде́ния!","パズドラヴリャーユ ズ ドニョーム ラジジェーニヤ！","поздравля́ть с＋造格で「〜おめでとう」。день → днём。"),
  ("子どもはスプーンで食べます。","Ребёнок ест ло́жкой.","リビョーナク イェースト ローシカイ。","道具の造格：ло́жка → ло́жкой。"),
  ("携帯電話を使ってもいいですか。","Мо́жно по́льзоваться телефо́ном?","モージナ ポーリザヴァッツァ チリフォーナム？","по́льзоваться＋造格で「〜を使う」。対格ではない点に注意。"),
 ]},
 {"unit":"Unit 22：生格 〜の／〜がない／数量","gp":"生格",
  "gDetail":"生格（родительный падеж）は ①所有「〜の」（名詞の後ろに置く）②否定 нет／не было「〜がない」③数量 мно́го, ско́лько, 2〜4（単数生格）, 5以上（複数生格）④前置詞 из, без, для, о́коло, по́сле, от, до, у の後 で使います。単数の語尾目安は 男性・中性 -а/-я、女性 -ы/-и。複数生格は -ов/-ев、-ей、語尾なし（я́блок, мест）の3タイプがあります。",
  "s":[
  ("これは兄の車です。","Это маши́на бра́та.","エータ マシーナ ブラータ。","「〜の」は名詞の後ろに生格を置きます。брат → бра́та。"),
  ("今日は時間がありません。","Сего́дня у меня́ нет вре́мени.","シヴォードニャ ウ ミニャー ニェト ヴリェーミニ。","нет＋生格で「〜がない」。вре́мя → вре́мени（特殊な変化）。"),
  ("家に牛乳がありません。","До́ма нет молока́.","ドーマ ニェト マラカー。","нет＋生格。молоко́ → молока́。"),
  ("私には兄弟が2人います。","У меня́ два бра́та.","ウ ミニャー ドヴァ ブラータ。","2・3・4の後ろは単数生格。два брат-а。"),
  ("教室には学生が5人います。","В кла́ссе пять студе́нтов.","フ クラーッシェ ピャーチ ストゥジェーンタフ。","5以上の後ろは複数生格。студе́нт → студе́нтов。"),
  ("私には友達がたくさんいます。","У меня́ мно́го друзе́й.","ウ ミニャー ムノーガ ドルジェーイ。","мно́го＋複数生格。друг → друзе́й（不規則）。"),
  ("りんごを1キロください。","Да́йте килогра́мм я́блок, пожа́луйста.","ダーイチェ キラグラーム ヤーブラク、パジャールスタ。","量＋複数生格。я́блоко → я́блок（語尾なし型）。"),
  ("水を1本ください。","Буты́лку воды́, пожа́луйста.","ブティールク ヴァディー、パジャールスタ。","容器＋中身の生格「〜の入った…」。вода́ → воды́。"),
  ("仕事の後で会いましょう。","Дава́йте встре́тимся по́сле рабо́ты.","ダヴァーイチェ フストリェーチムシャ ポースリェ ラボーティ。","по́сле＋生格で「〜の後で」。рабо́та → рабо́ты。"),
  ("私は砂糖なしでコーヒーを飲みます。","Я пью ко́фе без са́хара.","ヤー ピユー コーフィ ビス サーハラ。","без＋生格で「〜なしで」。са́хар → са́хара。"),
  ("これは子ども用のプレゼントです。","Это пода́рок для ребёнка.","エータ パダーラク ドリャ リビョーンカ。","для＋生格で「〜のための」。ребёнок → ребёнка（о が落ちます）。"),
  ("私たちは駅の近くに住んでいます。","Мы живём о́коло вокза́ла.","ミー ジヴョーム オーカラ ヴァグザーラ。","о́коло＋生格で「〜の近くに」。"),
  ("お子さんは何人ですか。","Ско́лько у вас дете́й?","スコーリカ ウ ヴァス ジチェーイ？","ско́лько＋複数生格。де́ти → дете́й。"),
  ("彼は家から職場まで歩いて通っています。","От до́ма до рабо́ты он хо́дит пешко́м.","アド ドーマ ダ ラボーティ オン ホージト ピシコーム。","от … до＋生格で「〜から〜まで」。習慣なので不定向 ходи́ть。"),
  ("空席がありません。","Здесь нет свобо́дных мест.","ズジェーシ ニェト スヴァボードニフ ミェースト。","нет＋複数生格。形容詞は -ых、ме́сто → мест（語尾なし型）。"),
 ]},
 {"unit":"Unit 23：動詞の体 完了体と不完了体","gp":"動詞の体",
  "gDetail":"ロシア語の動詞はほぼすべて 不完了体（過程・継続・習慣・反復）と 完了体（1回で完結・結果）のペアを持ちます。「毎日〜する」「〜しているところ」は不完了体、「〜し終えた」「（これから1回）〜する」は完了体。完了体の現在形は未来の意味になり、不完了体の未来は бу́ду＋不定詞 で作ります。否定の命令（〜しないで）は原則として不完了体を使います。",
  "s":[
  ("私は毎日手紙を書きます。","Я ка́ждый день пишу́ пи́сьма.","ヤー カージドゥイ ジェーニ ピシュー ピーシマ。","毎日の習慣 → 不完了体 писа́ть。"),
  ("私はもう手紙を書き終えました。","Я уже́ написа́л письмо́.","ヤー ウジェー ナピサール ピシモー。","結果が出た1回の動作 → 完了体 написа́ть。"),
  ("昨日は一晩中テレビを見ていました。","Вчера́ я весь ве́чер смотре́л телеви́зор.","フチラー ヤー ヴィェーシ ヴィェーチル スマトリェール チリヴィーザル。","続いていた過程（весь ве́чер）→ 不完了体。"),
  ("私はその映画をもう見ました。","Я уже́ посмотре́л э́тот фильм.","ヤー ウジェー パスマトリェール エータト フィーリム。","見終えた結果 → 完了体 посмотре́ть。"),
  ("明日電話します。","За́втра я позвоню́.","ザーフトラ ヤー パズヴァニュー。","完了体の現在形 = 未来（1回の動作）。"),
  ("明日は一日中働きます。","За́втра я бу́ду рабо́тать весь день.","ザーフトラ ヤー ブードゥ ラボータチ ヴィェーシ ジェーニ。","бу́ду＋不完了体の不定詞 = 継続する未来。"),
  ("毎朝私はコーヒーを飲みます。","Ка́ждое у́тро я пью ко́фе.","カージダエ ウートラ ヤー ピユー コーフィ。","習慣 → 不完了体 пить。"),
  ("コーヒーを飲み終えて出かけました。","Я вы́пил ко́фе и ушёл.","ヤー ヴィーピル コーフィ イ ウショール。","次々に完結した動作 → 完了体 вы́пить, уйти́。"),
  ("私は単語を全部覚えました。","Я вы́учил все слова́.","ヤー ヴィーウチル フシェ スラヴァー。","覚え切った結果 → 完了体 вы́учить。"),
  ("私は単語を覚えているところです。","Я учу́ слова́.","ヤー ウチュー スラヴァー。","途中の過程 → 不完了体 учи́ть。"),
  ("ドアを閉めてください。","Закро́йте дверь, пожа́луйста.","ザクローイチェ ドヴィェーリ、パジャールスタ。","1回きりの具体的な依頼 → 完了体の命令形。"),
  ("窓を開けないでください。","Не открыва́йте окно́, пожа́луйста.","ニ アトクリヴァーイチェ アクノー、パジャールスタ。","否定の命令（〜しないで）→ 不完了体。"),
  ("彼はよく鍵を忘れます。","Он ча́сто забыва́ет ключи́.","オン チャースタ ザビヴァーイト クリュチー。","ча́сто（よく）の反復 → 不完了体 забыва́ть。"),
  ("鍵を忘れてしまいました！","Я забы́л ключи́!","ヤー ザビール クリュチー！","1回の結果 → 完了体 забы́ть。"),
  ("夕食を作ったら電話するね。","Когда́ пригото́влю у́жин, позвоню́.","カグダー プリガトーヴリュ ウージン、パズヴァニュー。","未来の「〜し終えたら」→ 完了体の未来形を2つ並べます。"),
 ]},
 {"unit":"Unit 24：比較・好み нравиться／лучше／самый","gp":"比較・好み",
  "gDetail":"「好き」は2通り：любить＋対格／不定詞（〜が好き・〜するのが好き）と、与格＋нра́вится＋主格（〜には…が気に入っている）。нра́виться では好きな物が主語なので、複数なら нра́вятся、過去なら主語の性で понра́вился／понра́вилась になります。比較級は多くが -ее（тепле́е, быстре́е）、不規則な лу́чше, ху́же, бо́льше, ме́ньше, деше́вле, доро́же, ста́рше もあります。「〜より」は чем か生格。最上級は са́мый＋形容詞。",
  "s":[
  ("私はロシア料理が好きです。","Мне нра́вится ру́сская ку́хня.","ムニェ ンラーヴィッツァ ルースカヤ クーフニャ。","与格 мне＋нра́вится＋主格。好きな物（ку́хня）が主語です。"),
  ("私はロシアの歌が好きです。","Мне нра́вятся ру́сские пе́сни.","ムニェ ンラーヴャッツァ ルースキエ ピェースニ。","好きな物が複数なので нра́вятся。"),
  ("娘はこの映画が気に入りました。","До́чери понра́вился э́тот фильм.","ドーチリ パンラーヴィルシャ エータト フィーリム。","完了体の過去。主語 фильм（男性）に合わせて -ся の前が -л。"),
  ("今日は昨日より暖かいです。","Сего́дня тепле́е, чем вчера́.","シヴォードニャ チプリェーエ、チェム フチラー。","比較級 -ее＋чем「〜より」。тёплый → тепле́е。"),
  ("地下鉄はタクシーより速いです。","Метро́ быстре́е, чем такси́.","ミトロー ビストリェーエ、チェム タクシー。","бы́стрый → быстре́е。"),
  ("もう少しゆっくり話してください。","Говори́те, пожа́луйста, ме́дленнее.","ガヴァリーチェ、パジャールスタ、ミェードリンニエ。","副詞の比較級も -ее。ме́дленно → ме́дленнее。"),
  ("兄は私より年上です。","Брат ста́рше меня́.","ブラート スタールシェ ミニャー。","比較級＋生格で「〜より」。я → меня́。"),
  ("こちらのほうが安いです。","Э́то деше́вле.","エータ ジシェーヴリェ。","不規則な比較級 деше́вле（← дешёвый）。"),
  ("私はお茶よりコーヒーのほうが好きです。","Я бо́льше люблю́ ко́фе, чем чай.","ヤー ボーリシェ リュブリュー コーフィ、チェム チャーイ。","бо́льше люби́ть … чем …「〜より…のほうが好き」。"),
  ("これは町で一番大きな公園です。","Это са́мый большо́й парк в го́роде.","エータ サームイ バリショーイ パールク ヴ ゴーラジェ。","са́мый＋形容詞 = 最上級。парк（男性）に合わせて са́мый。"),
  ("彼女はクラスで一番背が高いです。","Она́ са́мая высо́кая в кла́ссе.","アナー サーマヤ ヴィソーカヤ フ クラーッシェ。","主語が女性なので са́мая высо́кая。"),
  ("どちらのほうがお好きですか。","Что вам бо́льше нра́вится?","シト ヴァム ボーリシェ ンラーヴィッツァ？","好む人は与格 вам。"),
  ("私は泳ぐのが好きです。","Я люблю́ пла́вать.","ヤー リュブリュー プラーヴァチ。","люби́ть＋不定詞「〜するのが好き」。"),
  ("一番大事なのは健康です。","Са́мое гла́вное — здоро́вье.","サーマエ グラーヴナエ — ズダローヴィエ。","са́мое гла́вное「一番大事なこと」（中性で「こと」を表す）。"),
  ("私は冬より夏のほうが好きです。","Ле́то мне нра́вится бо́льше, чем зима́.","リェータ ムニェ ンラーヴィッツァ ボーリシェ、チェム ジマー。","нра́вится бо́льше, чем …「〜より好き」。"),
 ]},
 {"unit":"Unit 25：複文 что／который／чтобы／если／когда","gp":"複文・接続詞",
  "gDetail":"文と文をつなぐ表現です。что「〜ということ」、кото́рый「〜する（名詞）」（性・数は前の名詞、格は節の中の役割）、что́бы「〜するために（＋不定詞）／〜するように（＋過去形）」、е́сли「もし〜なら」、когда́「〜するとき」、ли「〜かどうか」、хотя́「〜だけれど」、зато́「その代わり」。е́сли／когда́ の後ろで未来のことを言うときは、日本語と違って未来形を使います。コンマで節を区切るのが必須です。",
  "s":[
  ("彼は明日来ると言いました。","Он сказа́л, что придёт за́втра.","オン スカザール、シト プリジョート ザーフトラ。","что＋文「〜ということ」。что の前には必ずコンマ。"),
  ("あなたが正しいと思います。","Я ду́маю, что вы пра́вы.","ヤー ドゥーマユ、シト ヴィ プラーヴィ。","ду́мать, что …「〜だと思う」。"),
  ("これはモスクワに住んでいる友達です。","Это друг, кото́рый живёт в Москве́.","エータ ドルーク、カトールイ ジヴョート ヴ マスクヴィェー。","кото́рый：друг（男性）に合わせ、節の主語なので主格。"),
  ("これは私が働いている会社です。","Это компа́ния, в кото́рой я рабо́таю.","エータ カンパーニヤ、フ カトーライ ヤー ラボータユ。","в＋前置格 кото́рой（компа́ния は女性）。"),
  ("昨日買った本はおもしろいです。","Кни́га, кото́рую я купи́л вчера́, интере́сная.","クニーガ、カトールユ ヤー クピール フチラー、インチリェースナヤ。","купи́ть の目的語なので対格 кото́рую（女性）。"),
  ("ロシアで働くためにロシア語を勉強しています。","Я учу́ ру́сский, что́бы рабо́тать в Росси́и.","ヤー ウチュー ルースキイ、シトービ ラボータチ ヴ ラシーイ。","что́бы＋不定詞「〜するために」（主語が同じ）。"),
  ("子どもが眠れるように静かに話してください。","Говори́те ти́ше, что́бы ребёнок спал.","ガヴァリーチェ チーシェ、シトービ リビョーナク スパール。","主語が違うときは что́бы＋過去形。"),
  ("雨が降ったら家にいます。","Е́сли бу́дет дождь, я бу́ду до́ма.","イェースリ ブージト ドーシチ、ヤー ブードゥ ドーマ。","е́сли の中でも未来形 бу́дет を使います。"),
  ("時間があったら電話して。","Е́сли бу́дет вре́мя, позвони́.","イェースリ ブージト ヴリェーミャ、パズヴァニー。","е́сли＋未来、後半は命令形。"),
  ("家に着いたら書いてね。","Когда́ придёшь домо́й, напиши́.","カグダー プリジョーシ ダモーイ、ナピシー。","когда́＋完了体の未来「〜したら」。"),
  ("子どもの頃、私は田舎に住んでいました。","Когда́ я был ма́леньким, я жил в дере́вне.","カグダー ヤー ビル マーリンキム、ヤー ジル ヴ ジリェーヴニェ。","когда́＋過去。быть の後の形容詞は造格 ма́леньким。"),
  ("彼がどこに住んでいるか知りません。","Я не зна́ю, где он живёт.","ヤー ニ ズナーユ、グジェ オン ジヴョート。","疑問詞（где, когда́, куда́ …）で節をつなげます。"),
  ("彼女が来るかどうか分かりません。","Я не зна́ю, придёт ли она́.","ヤー ニ ズナーユ、プリジョート リ アナー。","動詞＋ли で「〜かどうか」。"),
  ("ここは高いけど、その代わり便利です。","Здесь до́рого, зато́ удо́бно.","ズジェーシ ドーラガ、ザトー ウドーブナ。","зато́「その代わり（良い点）」。"),
  ("疲れていたけど、仕事を終えました。","Хотя́ я уста́л, я зако́нчил рабо́ту.","ハチャー ヤー ウスタール、ヤー ザコーンチル ラボートゥ。","хотя́「〜だけれども」。"),
 ]},
 {"unit":"Unit 26：再帰動詞・否定・должен・свой","gp":"再帰動詞・否定",
  "gDetail":"-ся（母音の後は -сь）の付く再帰動詞は「自分を〜する」「（物事が）〜する」「互いに〜する」を表します（просыпа́ться, начина́ться, встреча́ться）。никто́, ничего́, никогда́, нигде́, никуда́ は必ず動詞の前の не と一緒に使います（二重否定が正しい形）。до́лжен／должна́／должны́＋不定詞は「〜しなければならない」。свой は「（主語）自身の」で、主語が誰でも同じ語を使い、修飾する名詞の性・数・格に合わせて変化します。",
  "s":[
  ("私は7時に起きます。","Я просыпа́юсь в семь.","ヤー プラシパーユシ フ シェーミ。","-ся 動詞。母音の後なので -сь（просыпа́ю-сь）。"),
  ("授業は9時に始まります。","Уро́к начина́ется в де́вять.","ウローク ナチナーイッツァ ヴ ジェーヴィチ。","物事が主語のときは -ся 動詞 начина́ться。"),
  ("店は何時に閉まりますか。","Во ско́лько закрыва́ется магази́н?","ヴァ スコーリカ ザクリヴァーイッツァ マガジーン？","закрыва́ться「（店が）閉まる」。時刻は во ско́лько? で尋ねます。"),
  ("私たちはモスクワで知り合いました。","Мы познако́мились в Москве́.","ミー パズナコーミリシ ヴ マスクヴィェー。","過去形の再帰動詞：-лся／-лась／-лись。"),
  ("彼女はいつもにこにこしています。","Она́ всегда́ улыба́ется.","アナー フシグダー ウリバーイッツァ。","улыба́ться（3人称単数 -ется）。"),
  ("誰も来ませんでした。","Никто́ не пришёл.","ニクトー ニ プリショール。","никто́＋не＋動詞。否定が2つ重なるのが正しい形です。"),
  ("私は何も分かりません。","Я ничего́ не понима́ю.","ヤー ニチヴォー ニ パニマーユ。","ничего́＋не。"),
  ("私はモスクワに一度も行ったことがありません。","Я никогда́ не́ был в Москве́.","ヤー ニカグダー ニェ ビル ヴ マスクヴィェー。","никогда́＋не。не́ был はアクセントが не に移ります。"),
  ("今日はどこにも行きません。","Сего́дня я никуда́ не иду́.","シヴォードニャ ヤー ニクダー ニ イドゥー。","никуда́「どこへも」（方向）＋не。"),
  ("私は早く帰らなければなりません。","Я до́лжен ра́но уйти́.","ヤー ドールジン ラーナ ウイチー。","до́лжен＋不定詞（主語が男性）。"),
  ("彼女は薬を飲まなければなりません。","Она́ должна́ принима́ть лека́рство.","アナー ダルジナー プリニマーチ リカールストヴァ。","主語が女性なので должна́。"),
  ("私たちは書類を見せなければなりません。","Мы должны́ показа́ть докуме́нты.","ミー ダルジニー パカザーチ ダクミェーンティ。","複数の主語は должны́。"),
  ("私は毎日自分の母に電話します。","Я звоню́ свое́й ма́ме ка́ждый день.","ヤー ズヴァニュー スヴァイェーイ マーミェ カージドゥイ ジェーニ。","свой「自分の」。ма́ме（与格・女性）に合わせて свое́й。"),
  ("彼は自分の車で来ました。","Он прие́хал на свое́й маши́не.","オン プリイェーハル ナ スヴァイェーイ マシーニェ。","на＋前置格 маши́не に合わせて свое́й。его́ だと「別の男性の」になり得ます。"),
  ("心配しないでください。","Не беспоко́йтесь.","ニ ビスパコーイチシ。","再帰動詞の命令形：-йте＋сь。"),
 ]},
 {"unit":"Unit 27：日付・序数・時刻","gp":"日付・序数",
  "gDetail":"日付は「序数（中性）＋月の生格」：пе́рвое ма́я（5月1日）。「〜日に」は序数の生格 пе́рвого ма́я、「〜年に」は в＋序数の前置格＋году́。階は на＋序数の前置格（на тре́тьем этаже́）。時刻は 1 час、2〜4 часа́、5〜 часо́в。「〜時に」は в＋対格（в два часа́）。че́рез＋対格「〜後に」、… наза́д「〜前に」、с … до …＋生格「〜から〜まで」、по＋複数与格「毎〜曜日に」も合わせて覚えます。",
  "s":[
  ("今日は何日ですか。","Како́е сего́дня число́?","カコーエ シヴォードニャ チスロー？","日付は число́（中性）で尋ねるので како́е。"),
  ("今日は5月1日です。","Сего́дня пе́рвое ма́я.","シヴォードニャ ピェールヴァエ マーヤ。","序数の中性形（число́ に合わせる）＋月の生格。"),
  ("私の誕生日は3月8日です。","Мой день рожде́ния восьмо́го ма́рта.","モーイ ジェーニ ラジジェーニヤ ヴァシモーヴァ マールタ。","「〜日に」は序数の生格：восьмо́го ма́рта。"),
  ("私は1990年に生まれました。","Я родила́сь в ты́сяча девятьсо́т девяно́стом году́.","ヤー ラジラーシ フ ティーシチャ ジヴィツォート ジヴィノースタム ガドゥー。","в＋最後の数だけ序数の前置格＋году́。"),
  ("私たちは10日に出発します。","Мы уезжа́ем деся́того.","ミー ウイジジャーイム ジシャータヴァ。","「〜日に」は序数の生格だけでも言えます。"),
  ("私は3階に住んでいます。","Я живу́ на тре́тьем этаже́.","ヤー ジヴー ナ トリェーチエム エタジェー。","на＋序数の前置格＋этаже́。тре́тий は特殊な変化。"),
  ("私はロシアは初めてです。","Я в Росси́и пе́рвый раз.","ヤー ヴ ラシーイ ピェールヴイ ラース。","пе́рвый раз「初めて・1回目」。序数 пе́рвый は形容詞と同じ変化。"),
  ("今何時ですか。","Кото́рый час?","カトールイ チャース？","時刻を尋ねる定型表現。Ско́лько вре́мени? とも言います。"),
  ("今3時です。","Сейча́с три часа́.","シチャース トリー チサー。","2〜4の後は単数生格 часа́。"),
  ("今5時30分です。","Сейча́с пять часо́в три́дцать мину́т.","シチャース ピャーチ チソーフ トリーッツァチ ミヌート。","5以上は複数生格 часо́в、мину́т。"),
  ("会議は2時に始まります。","Встре́ча начина́ется в два часа́.","フストリェーチャ ナチナーイッツァ ヴ ドヴァ チサー。","「〜時に」は в＋時刻。"),
  ("30分後に戻ります。","Я верну́сь че́рез полчаса́.","ヤー ヴィルヌーシ チェーリス ポルチサー。","че́рез＋時間「〜後に」。"),
  ("私は2日前に来ました。","Я прие́хал два дня наза́д.","ヤー プリイェーハル ドヴァ ドニャー ナザート。","時間＋наза́д「〜前に」。день → дня（2〜4＋単数生格）。"),
  ("授業は月曜日から金曜日まであります。","Уро́ки с понеде́льника до пя́тницы.","ウローキ ス パニジェーリニカ ダ ピャートニツィ。","с … до …＋生格「〜から〜まで」。"),
  ("毎週土曜日に祖母のところへ行きます。","По суббо́там я е́зжу к ба́бушке.","パ スボータム ヤー イェージュ ク バーブシュキェ。","по＋複数与格「毎〜曜日に」。к＋与格「〜のところへ」。"),
 ]},
]
